// Gamepad value index — record JAH-GPCS-GAMEPAD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"buttons": 16, "battery_h": 30, "price_usd": 60};
var value = (m.buttons*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-GAMEPAD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-GAMEPAD-000001|' + value.toFixed(2) + ' value index');

